window.HOEREN_TESTS[61] = {"id":"auf-dem-wochenmarkt","name":"Auf dem Wochenmarkt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Marktbesucher: Der Wochenmarkt findet ab April nicht mehr nur am Samstag statt, sondern auch mittwochs. Mittwochs aber kleiner — nur Obst, Gemüse und Blumen. Nur Fisch gibt es nie, mittwochs nur Obst, Gemüse und Blumen. Samstags wie immer das volle Angebot mit Käse, Fisch und Fleisch. Wir freuen uns auf euch!","gender":"f","q":"Was gibt es mittwochs auf dem Markt?","opts":["Das volle Angebot.","Nur Obst, Gemüse und Blumen.","Nur Fisch."],"correct":1},{"transcript":"Hallo Mama, hier ist Anna. Ich bin auf dem Markt. Die Erdbeeren sind heute super günstig, eine Schale nur 2 Euro. Soll ich zwei nehmen? Und der Spargel ist auch da, aber teuer. Blumen kaufe ich nicht, nur Erdbeeren. Sag mir bitte schnell Bescheid, sonst sind die Erdbeeren weg. Tschüs!","gender":"f","q":"Was ist heute günstig?","opts":["Der Spargel.","Die Blumen.","Die Erdbeeren."],"correct":2},{"transcript":"Achtung Kunden: Unser Fischstand bleibt heute geschlossen. Der Lieferwagen hatte eine Panne, leider kein frischer Fisch. Ab nächstem Samstag sind wir wieder da. Der Gemüsestand ist offen, nur der Fisch fehlt heute. Der Käsestand nebenan ist normal geöffnet. Wir bitten um Entschuldigung und danken für Ihr Verständnis!","gender":"m","q":"Welcher Stand ist heute geschlossen?","opts":["Der Käsestand.","Der Gemüsestand.","Der Fischstand."],"correct":2},{"transcript":"Hi Tom, hier ist Markus. Ich mache morgen ein großes Essen und brauche Hilfe beim Einkaufen auf dem Markt. Ich brauche frisches Gemüse und Kräuter — nicht aus dem Supermarkt, sondern vom Bauern direkt. Kein Fleisch und kein Brot, nur Gemüse und Kräuter. Kommst du mit um 9 Uhr? Der Markt ist früh am besten!","gender":"m","q":"Was möchte Markus auf dem Markt kaufen?","opts":["Gemüse und Kräuter.","Fleisch und Wurst.","Brot und Kuchen."],"correct":0},{"transcript":"Liebe Besucher: Am letzten Samstag im Monat gibt es ein Markt-Fest. Viele Stände bieten Kostproben gratis an, dazu Live-Musik. Für Kinder gibt es ein Karussell. Der Eintritt ist frei. Keine 5 Euro und keine 2 Euro, der Eintritt ist wirklich frei. Kommen Sie vorbei und probieren Sie regionale Produkte! Wir freuen uns!","gender":"f","q":"Was kostet der Eintritt zum Markt-Fest?","opts":["Er ist frei.","5 Euro.","2 Euro."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Wochenmarkt ist heute bis eins auf dem Platz."},{"speaker":"Lisa","gender":"f","text":"Ich habe den Korb schon dabei. Wir verteilen die Stände kurz unter uns."},{"speaker":"Lukas","gender":"m","text":"Ich kaufe Fisch an dem blauen Stand. Der Händler hat heute frische Forellen."},{"speaker":"Lisa","gender":"f","text":"Ich nehme Blumen für unsere Küche. Gelbe Tulpen stehen vorn im Eimer."},{"speaker":"Lukas","gender":"m","text":"Nehmen wir auch Fleisch und Wurst vom Grillstand mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Fleisch und Wurst kaufen wir nicht. Der Stand ist uns einfach zu teuer."},{"speaker":"Lukas","gender":"m","text":"Tom will abends etwas Herzhaftes für die ganze Familie."},{"speaker":"Lisa","gender":"f","text":"Tom nimmt Käse beim Bauern mit. Ein Stück davon reicht für mehrere Tage."},{"speaker":"Lukas","gender":"m","text":"Sara kommt mit einer großen leeren Tüte zum Platz."},{"speaker":"Lisa","gender":"f","text":"Sara füllt Obst in die große Tüte. Äpfel und Birnen legt sie oben hinein."},{"speaker":"Lukas","gender":"m","text":"Brauchen wir ein frisches Brot vom Bäcker?"},{"speaker":"Lisa","gender":"f","text":"Nein. Brot brauchen wir heute nicht. Zu Hause liegt noch ein halber Laib."},{"speaker":"Lukas","gender":"m","text":"Tim nimmt nie Zucker aus dem Supermarkt in den Tee."},{"speaker":"Lisa","gender":"f","text":"Tim nimmt Honig beim Imker mit. Das Glas kommt direkt aus dem Dorf."},{"speaker":"Lukas","gender":"m","text":"Dann teilen wir uns an den Ständen auf."},{"speaker":"Lisa","gender":"f","text":"Wir treffen uns um zwölf wieder beim Brunnen."}],"options":[{"letter":"a","text":"Obst"},{"letter":"b","text":"Eier"},{"letter":"c","text":"Käse"},{"letter":"d","text":"Fleisch und Wurst"},{"letter":"e","text":"Blumen"},{"letter":"f","text":"Gemüse"},{"letter":"g","text":"Fisch"},{"letter":"h","text":"Honig"},{"letter":"i","text":"Brot"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"c"},{"person":"Sara","correct":"a"},{"person":"Tim","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Was kostet das Kilo Tomaten?"},{"speaker":"Händler","gender":"m","text":"Normale 3 Euro 50, Bio-Tomaten 4 Euro. Zwei Kilo kosten 7 Euro 50."},{"speaker":"Kundin","gender":"f","text":"Dann ein Kilo Bio für 4 Euro, bitte."},{"speaker":"Händler","gender":"m","text":"Gern! Macht 4 Euro. Sonst noch etwas? Schönes?"},{"speaker":"Kundin","gender":"f","text":"Nein danke, das ist alles. Tschüss für heute!"},{"speaker":"Kundin","gender":"f","text":"Ach ja, noch ein Bund Petersilie dazu, bitte!"}],"q":"Was bezahlt die Kundin?","opts":["3 Euro 50.","4 Euro.","7 Euro 50."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag! Sind die Äpfel aus der Region?"},{"speaker":"Bäuerin","gender":"f","text":"Ja, vom Hof gleich nebenan. Frisch von gestern, sehr lecker!"},{"speaker":"Mann","gender":"m","text":"Und die Orangen? Auch aus der Region?"},{"speaker":"Bäuerin","gender":"f","text":"Die nicht, die kommen aus Spanien. Italien haben wir selten."},{"speaker":"Mann","gender":"m","text":"Gut, dann nehme ich zwei Kilo Äpfel aus der Region. Danke!"}],"q":"Woher kommen die Äpfel?","opts":["Aus Spanien.","Aus der Region.","Aus Italien."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Haben Sie noch Spargel? Weißen oder grünen?"},{"speaker":"Händler","gender":"m","text":"Der weiße ist leider aus. Nur noch grüner Spargel da."},{"speaker":"Frau","gender":"f","text":"Schade! Ganz ohne Spargel will ich nicht gehen."},{"speaker":"Händler","gender":"m","text":"Dann nehmen Sie grünen, der schmeckt auch gut. 5 Euro das Bund."},{"speaker":"Frau","gender":"f","text":"Gut, dann ein Bund grünen Spargel, bitte!"}],"q":"Welchen Spargel kauft die Frau?","opts":["Grünen.","Weißen.","Keinen."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Wann bauen Sie morgens auf? Um 7 Uhr?"},{"speaker":"Händlerin","gender":"f","text":"Ja, wir sind ab 7 Uhr da. Um 12 Uhr ist am meisten los."},{"speaker":"Kunde","gender":"m","text":"Und wann ist Schluss? Wann packen Sie zusammen?"},{"speaker":"Händlerin","gender":"f","text":"Um 14 Uhr packen wir zusammen. Dann ist der Markt zu Ende."},{"speaker":"Kunde","gender":"m","text":"Verstanden, bis 14 Uhr! Danke und tschüss!"}],"q":"Wann endet der Markt?","opts":["Um 7 Uhr.","Um 12 Uhr.","Um 14 Uhr."],"correct":2},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, darf ich den Honig probieren? Bitte!"},{"speaker":"Vater","gender":"m","text":"Frag den Imker. Und die Marmelade dort sieht auch gut aus, oder?"},{"speaker":"Imker","gender":"m","text":"Klar, hier ein Löffel Blütenhonig für dich!"},{"speaker":"Tochter","gender":"f","text":"Mmm, lecker! Den Honig nehmen wir, keine Marmelade!"},{"speaker":"Vater","gender":"m","text":"Und Käse nehmen wir auch noch mit. Zahlt der Papa, heute."}],"q":"Was probiert die Tochter?","opts":["Marmelade.","Käse.","Honig."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Hofer, einer Bäuerin auf dem Wochenmarkt. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Hofer, was verkaufen Sie auf dem Markt?"},{"speaker":"Hofer","gender":"f","text":"Alles von meinem eigenen Hof, nur das. Gemüse, Salate und im Sommer auch Beeren. Nichts dazu gekauft, alles selbst angebaut. Keine Chemie, alles natürlich."},{"speaker":"Reporter","gender":"m","text":"Wie sieht Ihr Tag aus?"},{"speaker":"Hofer","gender":"f","text":"Sehr früh, wirklich. Ich stehe um vier Uhr auf, nicht erst um sieben, und fahre in die Stadt. Um sechs baue ich den Stand auf, pünktlich um sieben geht es los."},{"speaker":"Reporter","gender":"m","text":"Warum kaufen die Leute bei Ihnen?"},{"speaker":"Hofer","gender":"f","text":"Wegen der Frische, ganz klar. Mein Gemüse ist von gestern, nicht von letzter Woche wie im Supermarkt. Das schmeckt man. Das schmeckt man sofort."},{"speaker":"Reporter","gender":"m","text":"Ist es schwer, von einem kleinen Hof zu leben?"},{"speaker":"Hofer","gender":"f","text":"Ja, das ist es, sehr schwer. Ohne den Markt würden wir es nicht schaffen, das sage ich ehrlich. Der Hof allein reicht nicht. Der Hof allein reicht nicht zum Leben."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich für die Zukunft?"},{"speaker":"Hofer","gender":"f","text":"Dass mehr junge Leute wieder auf dem Markt einkaufen. Sie kochen wieder mehr selbst, das sehe ich. Das freut mich. Das freut mich sehr."}],"items":[{"q":"Frau Hofer steht erst um sieben Uhr auf.","correct":"nein"},{"q":"Sie verkauft nur Sachen von ihrem eigenen Hof.","correct":"ja"},{"q":"Die Leute kaufen bei ihr wegen der Frische.","correct":"ja"},{"q":"Ohne den Markt könnte ihr Hof gut leben.","correct":"nein"},{"q":"Sie wünscht sich mehr junge Kunden auf dem Markt.","correct":"ja"}]}]};
